require_once __DIR__ . '/layout.php';$uid=(int)$_SESSION['user_id'];$fy=(int)($_GET['fy']??leave_fiscal_year());$filter=trim((string)($_GET['filter']??'pending'));
$where="fiscal_year={$fy}";if(!leave_is_admin())$where.=" AND supervisor_user_id={$uid}";if($filter==='pending')$where.=" AND status IN ('pending_supervisor','cancel_requested')";elseif($filter==='done')$where.=" AND status IN ('approved','rejected','cancelled')";$rows=array();$res=$conn->query("SELECT * FROM leave_applications WHERE {$where} ORDER BY (status IN ('pending_supervisor','cancel_requested')) DESC,id DESC LIMIT 200");while($res&&$r=$res->fetch_assoc())$rows[]=$r;
leave_page_start('อนุมัติใบลา','หัวหน้างานตรวจสอบการรับมอบงาน เหตุผลการลา และพิจารณาเห็นชอบ','approval');
?>
<section class="leave-card"><div class="leave-card__head"><div><h2>รายการรอเห็นชอบ</h2><p><?=leave_is_admin()?'Admin สามารถพิจารณารายการทั้งหมดได้':'แสดงเฉพาะรายการที่กำหนดให้คุณเป็นหัวหน้างาน'?></p></div></div><div class="leave-card__body"><form class="leave-filter" method="get"><div class="leave-field"><label>ปีงบประมาณ</label><select class="leave-select" name="fy"><?php for($y=leave_fiscal_year()+1;$y>=leave_fiscal_year()-4;$y--):?><option value="<?=$y?>" <?=$fy===$y?'selected':''?>><?=$y?></option><?php endfor;?></select></div><div class="leave-field"><label>รายการ</label><select class="leave-select" name="filter"><option value="pending" <?=$filter==='pending'?'selected':''?>>รอดำเนินการ</option><option value="done" <?=$filter==='done'?'selected':''?>>ดำเนินการแล้ว</option><option value="all" <?=$filter==='all'?'selected':''?>>ทั้งหมด</option></select></div><button class="leave-btn leave-btn--secondary">แสดงข้อมูล</button></form></div><div class="leave-table-wrap"><table class="leave-table"><thead><tr><th>เลขที่</th><th>ผู้ลา / หน่วยงาน</th><th>ประเภท</th><th>ช่วงวันลา</th><th>รับมอบงาน</th><th>สถานะ</th><th>คำสั่ง</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7"><div class="leave-empty">ไม่มีรายการสำหรับพิจารณา</div></td></tr><?php endif;?><?php foreach($rows as $r):$si=leave_status_info($r['status']);$hi=leave_handover_info($r['handover_status']);?><tr><td><strong><?=leave_e($r['leave_no'])?></strong></td><td><?=leave_e($r['employee_name'])?><br><small><?=leave_e($r['department_name'])?></small></td><td><?=leave_e($r['leave_type_name'])?></td><td><?=leave_date_thai($r['start_date'])?> – <?=leave_date_thai($r['end_date'])?><br><small><?=leave_format_days($r['leave_days'])?> วัน</small></td><td><?=leave_e($r['handover_name'])?><br><span class="leave-badge leave-badge--<?=$hi[1]?>"><?=leave_e($hi[0])?></span></td><td><span class="leave-badge leave-badge--<?=$si[1]?>"><?=leave_e($si[0])?></span></td><td><a class="leave-btn leave-btn--sm leave-btn--primary" href="detail.php?id=<?=$r['id']?>">พิจารณา / รายละเอียด</a></td></tr><?php endforeach;?></tbody></table></div></section>
<?php leave_page_end(); ?>
